package com.example.order;

import static org.assertj.core.api.Assertions.assertThat;

import com.fasterxml.jackson.databind.JsonNode;
import com.sun.net.httpserver.HttpServer;
import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.client.TestRestTemplate;
import org.springframework.boot.testcontainers.service.connection.ServiceConnection;
import org.springframework.http.*;
import org.springframework.test.context.DynamicPropertyRegistry;
import org.springframework.test.context.DynamicPropertySource;
import org.testcontainers.containers.PostgreSQLContainer;
import org.testcontainers.junit.jupiter.Container;
import org.testcontainers.junit.jupiter.Testcontainers;

@Testcontainers
@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT, properties = {"order.expiry-sweep-enabled=false"})
class TmpConcTest {
    @Container @ServiceConnection
    static PostgreSQLContainer<?> postgres = new PostgreSQLContainer<>("postgres:16-alpine");
    static final HttpServer PG = startPg();
    @DynamicPropertySource
    static void gw(DynamicPropertyRegistry r) { r.add("payment.gateway.url", () -> "http://127.0.0.1:" + PG.getAddress().getPort()); }
    @Autowired TestRestTemplate rest;

    ResponseEntity<JsonNode> post(String path, Object body, String... h) {
        HttpHeaders headers = new HttpHeaders();
        headers.setContentType(MediaType.APPLICATION_JSON);
        for (int i = 0; i < h.length; i += 2) headers.add(h[i], h[i + 1]);
        return rest.exchange(path, HttpMethod.POST, new HttpEntity<>(body, headers), JsonNode.class);
    }

    <T> List<T> parallel(int n, java.util.function.IntFunction<T> f) throws Exception {
        ExecutorService ex = Executors.newFixedThreadPool(n);
        CountDownLatch go = new CountDownLatch(1);
        List<Future<T>> fs = new ArrayList<>();
        for (int i = 0; i < n; i++) { final int k = i; fs.add(ex.submit(() -> { go.await(); return f.apply(k); })); }
        go.countDown();
        List<T> out = new ArrayList<>();
        for (var f2 : fs) out.add(f2.get());
        ex.shutdown();
        return out;
    }

    @Test
    void conc() throws Exception {
        long p = post("/api/products", Map.of("name","p","price",100,"stock",5)).getBody().get("id").asLong();
        post("/api/coupons", Map.of("code","L","type","FIXED","value",10,"totalQuantity",3,"validFrom","2020-01-01T00:00:00Z","validUntil","2099-01-01T00:00:00Z"));
        var res = parallel(20, i -> post("/api/orders", Map.of("items", List.of(Map.of("productId", p, "quantity", 1)), "couponCode", "L"),
                "X-User-Id","u","Idempotency-Key","c"+i).getStatusCode().value());
        System.out.println("CONC oversell statuses " + res.stream().collect(java.util.stream.Collectors.groupingBy(x -> x, java.util.stream.Collectors.counting())));
        System.out.println("CONC product " + rest.getForObject("/api/products/" + p, JsonNode.class));
        System.out.println("CONC coupon " + rest.getForObject("/api/coupons/L", JsonNode.class));

        long p2 = post("/api/products", Map.of("name","p","price",100,"stock",50)).getBody().get("id").asLong();
        var same = parallel(10, i -> post("/api/orders", Map.of("items", List.of(Map.of("productId", p2, "quantity", 2))),
                "X-User-Id","u","Idempotency-Key","same").getBody().get("id").asLong());
        System.out.println("CONC same key ids " + new HashSet<>(same) + " product " + rest.getForObject("/api/products/" + p2, JsonNode.class));

        // pay vs cancel
        long o = post("/api/orders", Map.of("items", List.of(Map.of("productId", p2, "quantity", 1))), "X-User-Id","u","Idempotency-Key","pc").getBody().get("id").asLong();
        var r = parallel(2, i -> i == 0 ? post("/api/orders/" + o + "/pay", Map.of("cardToken","tok"), "Idempotency-Key","pcpay").getStatusCode().value()
                : post("/api/orders/" + o + "/cancel", null).getStatusCode().value());
        System.out.println("CONC pay/cancel " + r + " final " + rest.getForObject("/api/orders/" + o, JsonNode.class).get("status") + " " + rest.getForObject("/api/products/" + p2, JsonNode.class));
        // same pay key concurrent
        long o2 = post("/api/orders", Map.of("items", List.of(Map.of("productId", p2, "quantity", 1))), "X-User-Id","u","Idempotency-Key","pp").getBody().get("id").asLong();
        var r2 = parallel(5, i -> post("/api/orders/" + o2 + "/pay", Map.of("cardToken","tok"), "Idempotency-Key","samepay").getStatusCode().value());
        System.out.println("CONC samepay " + r2 + " PG calls " + CALLS.get());
    }
    static final java.util.concurrent.atomic.AtomicInteger CALLS = new java.util.concurrent.atomic.AtomicInteger();
    static HttpServer startPg() {
        try {
            HttpServer s = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
            s.setExecutor(Executors.newFixedThreadPool(8));
            s.createContext("/v1/payments", ex -> {
                ex.getRequestBody().readAllBytes(); CALLS.incrementAndGet();
                try { Thread.sleep(300); } catch (Exception e) {}
                String resp = ex.getRequestURI().getPath().endsWith("/refund") ? "{\"paymentId\":\"x\",\"status\":\"REFUNDED\"}" : "{\"paymentId\":\"pay-1\",\"status\":\"APPROVED\"}";
                byte[] b = resp.getBytes(StandardCharsets.UTF_8);
                ex.getResponseHeaders().add("Content-Type", "application/json");
                ex.sendResponseHeaders(200, b.length); ex.getResponseBody().write(b); ex.close();
            });
            s.start(); return s;
        } catch (IOException e) { throw new IllegalStateException(e); }
    }
}
EOF
