30	
31	/** RFC 9457 Problem Details for every error (type = https://example.com/problems/{slug}, extension "code"). */
32	@RestControllerAdvice
33	public class GlobalExceptionHandler extends ResponseEntityExceptionHandler {
34	
35	    private static final Logger log = LoggerFactory.getLogger(GlobalExceptionHandler.class);
36	    private static final String TYPE_BASE = "https://example.com/problems/";
37	
38	    @ExceptionHandler(ApiException.class)
39	    public ResponseEntity<Object> handleApi(ApiException ex, HttpServletRequest request) {
40	        ProblemDetail pd = problem(ex.getStatus(), ex.getSlug(), ex.getTitle(), ex.getMessage(), request.getRequestURI());
41	        ex.getExtensions().forEach(pd::setProperty);
42	        return respond(pd, new HttpHeaders());
43	    }
44	
45	    @ExceptionHandler(Exception.class)
46	    public ResponseEntity<Object> handleUnexpected(Exception ex, HttpServletRequest request) {
47	        log.error("Unexpected error on {} {}", request.getMethod(), request.getRequestURI(), ex);
48	        ProblemDetail pd = problem(HttpStatus.INTERNAL_SERVER_ERROR, "internal-error", "Internal server error",
49	                "An unexpected error occurred.", request.getRequestURI());
50	        return respond(pd, new HttpHeaders());
51	    }
52	
53	    @Override
54	    protected ResponseEntity<Object> handleMethodArgumentNotValid(MethodArgumentNotValidException ex,
55	            HttpHeaders headers, HttpStatusCode status, WebRequest request) {
56	        List<FieldViolation> errors = new java.util.ArrayList<>();
57	        ex.getBindingResult().getFieldErrors().stream()
58	                .sorted(Comparator.comparing(fe -> fe.getField()))
59	                .forEach(fe -> errors.add(new FieldViolation(fe.getField(), fe.getDefaultMessage())));
60	        ex.getBindingResult().getGlobalErrors()
61	                .forEach(ge -> errors.add(new FieldViolation(ge.getObjectName(), ge.getDefaultMessage())));
62	        ProblemDetail pd = problem(HttpStatus.BAD_REQUEST, "validation-failed", "Validation failed",
63	                "Request validation failed.", path(request));
64	        pd.setProperty("errors", errors);
65	        return respond(pd, headers);
66	    }
67	
68	    @Override
69	    protected ResponseEntity<Object> handleHttpMessageNotReadable(HttpMessageNotReadableException ex,
70	            HttpHeaders headers, HttpStatusCode status, WebRequest request) {
71	        // fixed text: never echo the request body (it may contain cardToken)
72	        ProblemDetail pd = problem(HttpStatus.BAD_REQUEST, "malformed-request", "Malformed request",
73	                "The request body is missing, not valid JSON, or has a field of the wrong type.", path(request));
74	        return respond(pd, headers);
75	    }
76	
77	    @Override
78	    protected ResponseEntity<Object> handleTypeMismatch(TypeMismatchException ex, HttpHeaders headers,
79	            HttpStatusCode status, WebRequest request) {
80	        String name = ex.getPropertyName() == null ? "unknown" : ex.getPropertyName();
81	        ProblemDetail pd = problem(HttpStatus.BAD_REQUEST, "invalid-parameter", "Invalid parameter",
82	                "Parameter '" + name + "' has an invalid value.", path(request));
83	        pd.setProperty("parameter", name);
84	        return respond(pd, headers);
85	    }
86	
87	    @Override
88	    protected ResponseEntity<Object> handleServletRequestBindingException(ServletRequestBindingException ex,
89	            HttpHeaders headers, HttpStatusCode status, WebRequest request) {
90	        if (ex instanceof MissingRequestHeaderException m) {
91	            ProblemDetail pd = problem(HttpStatus.BAD_REQUEST, "missing-required-header", "Missing required header",
92	                    "Required header '" + m.getHeaderName() + "' is missing.", path(request));
93	            pd.setProperty("header", m.getHeaderName());
94	            return respond(pd, headers);
95	        }
96	        return super.handleServletRequestBindingException(ex, headers, status, request);
97	    }
98	
99	    /** Remaining framework errors (405, 415, 404 ...) get the same shape. */
100	    @Override
101	    protected ResponseEntity<Object> handleExceptionInternal(Exception ex, Object body, HttpHeaders headers,
102	            HttpStatusCode statusCode, WebRequest request) {
103	        ResponseEntity<Object> base = super.handleExceptionInternal(ex, body, headers, statusCode, request);
104	        ProblemDetail pd = base.getBody() instanceof ProblemDetail p ? p : ProblemDetail.forStatus(statusCode);
105	        if (pd.getProperties() == null || !pd.getProperties().containsKey("code")) {
106	            String slug = slugFor(ex, statusCode);
107	            pd.setType(URI.create(TYPE_BASE + slug));
108	            if (pd.getTitle() == null) {
109	                pd.setTitle(titleFor(statusCode));
110	            }
111	            if (statusCode.is5xxServerError()) {
112	                pd.setDetail("An unexpected error occurred.");
113	            }
114	            pd.setInstance(toUri(path(request)));
115	            pd.setProperty("code", codeOf(slug));
116	        }
117	        HttpHeaders out = new HttpHeaders();
118	        out.putAll(base.getHeaders());
119	        return respond(pd, out);
120	    }
121	
122	    private static String slugFor(Exception ex, HttpStatusCode status) {
123	        if (ex instanceof HttpRequestMethodNotSupportedException) {
124	            return "method-not-allowed";
125	        }
126	        if (ex instanceof HttpMediaTypeNotSupportedException) {
127	            return "unsupported-media-type";
128	        }
129	        if (ex instanceof HttpMediaTypeNotAcceptableException) {
130	            return "not-acceptable";
131	        }
132	        if (ex instanceof NoResourceFoundException || ex instanceof NoHandlerFoundException || status.value() == 404) {
133	            return "resource-not-found";
134	        }
135	        if (status.is5xxServerError()) {
136	            return "internal-error";
137	        }
138	        return "malformed-request";
139	    }
140	
141	    private static String titleFor(HttpStatusCode status) {
142	        HttpStatus resolved = HttpStatus.resolve(status.value());
143	        return resolved == null ? "Error" : resolved.getReasonPhrase();
144	    }
145	
146	    private static ProblemDetail problem(HttpStatus status, String slug, String title, String detail, String path) {
147	        ProblemDetail pd = ProblemDetail.forStatusAndDetail(status, detail);
148	        pd.setType(URI.create(TYPE_BASE + slug));
149	        pd.setTitle(title);
150	        pd.setInstance(toUri(path));
151	        pd.setProperty("code", codeOf(slug));
152	        return pd;
153	    }
154	
155	    private static ResponseEntity<Object> respond(ProblemDetail pd, HttpHeaders headers) {
156	        HttpHeaders out = new HttpHeaders();
157	        out.putAll(headers);
158	        out.setContentType(MediaType.APPLICATION_PROBLEM_JSON);
159	        return new ResponseEntity<>(pd, out, HttpStatusCode.valueOf(pd.getStatus()));
160	    }
161	
162	    private static String codeOf(String slug) {
163	        return slug.toUpperCase().replace('-', '_');
164	    }
165	
166	    private static String path(WebRequest request) {
167	        return request instanceof ServletWebRequest swr ? swr.getRequest().getRequestURI() : "/";
168	    }
169	
170	    private static URI toUri(String path) {
171	        try {
172	            return URI.create(path);
173	        } catch (IllegalArgumentException e) {
174	            return URI.create("/");
175	        }
176	    }
177	}
