1	package com.example.order.coupon;
2	
3	import com.example.order.common.FieldViolation;
4	import com.example.order.common.Problems;
5	import com.example.order.common.TimeSupport;
6	import com.example.order.coupon.CouponDtos.CouponResponse;
7	import com.example.order.coupon.CouponDtos.CreateCouponRequest;
8	import java.time.Clock;
9	import java.time.temporal.ChronoUnit;
10	import java.util.ArrayList;
11	import java.util.List;
12	import org.hibernate.exception.ConstraintViolationException;
13	import org.springframework.dao.DataIntegrityViolationException;
14	import org.springframework.stereotype.Service;
15	
16	@Service
17	public class CouponService {
18	
19	    private static final String UNIQUE_CODE = "uq_coupons_code";
20	
21	    private final CouponRepository couponRepository;
22	    private final Clock clock;
23	
24	    public CouponService(CouponRepository couponRepository, Clock clock) {
25	        this.couponRepository = couponRepository;
26	        this.clock = clock;
27	    }
28	
29	    /** Not transactional on purpose: the unique violation surfaces from saveAndFlush and is translated to 409. */
30	    public CouponResponse create(CreateCouponRequest r) {
31	        validateCrossFields(r);
32	        Coupon coupon = new Coupon(r.code(), r.type(), r.value(),
33	                r.minOrderAmount() == null ? 0L : r.minOrderAmount(), r.maxDiscountAmount(),
34	                r.totalQuantity().intValue(), r.validFrom().truncatedTo(ChronoUnit.MICROS),
35	                r.validUntil().truncatedTo(ChronoUnit.MICROS), TimeSupport.now(clock));
36	        try {
37	            return CouponResponse.from(couponRepository.saveAndFlush(coupon));
38	        } catch (DataIntegrityViolationException e) {
39	            if (isCodeDuplicate(e)) {
40	                throw Problems.couponCodeDuplicated(r.code());
41	            }
42	            throw e;
43	        }
44	    }
45	
46	    public CouponResponse get(String code) {
47	        return couponRepository.findByCode(code).map(CouponResponse::from)
48	                .orElseThrow(() -> Problems.couponNotFound(code));
49	    }
50	
51	    private static void validateCrossFields(CreateCouponRequest r) {
52	        List<FieldViolation> errors = new ArrayList<>();
53	        if (r.type() == CouponType.RATE && r.value() > 100) {
54	            errors.add(new FieldViolation("value", "must be between 1 and 100 for RATE coupons"));
55	        }
56	        if (r.type() == CouponType.FIXED && r.value() > 1_000_000_000L) {
57	            errors.add(new FieldViolation("value", "must be at most 1000000000 for FIXED coupons"));
58	        }
59	        if (!r.validFrom().isBefore(r.validUntil())) {
60	            errors.add(new FieldViolation("validUntil", "must be after validFrom"));
61	        }
62	        if (!errors.isEmpty()) {
63	            throw Problems.validation(errors);
64	        }
65	    }
66	
67	    private static boolean isCodeDuplicate(Throwable e) {
68	        for (Throwable t = e; t != null; t = t.getCause()) {
69	            if (t instanceof ConstraintViolationException cve && UNIQUE_CODE.equalsIgnoreCase(cve.getConstraintName())) {
70	                return true;
71	            }
72	            if (t.getMessage() != null && t.getMessage().contains(UNIQUE_CODE)) {
73	                return true;
74	            }
75	        }
76	        return false;
77	    }
78	}
