1	package com.example.order.order;
2	
3	import com.example.order.common.Problems;
4	import com.example.order.common.TimeSupport;
5	import com.example.order.order.OrderDtos.OrderPage;
6	import com.example.order.order.OrderDtos.OrderResponse;
7	import jakarta.persistence.EntityManager;
8	import jakarta.persistence.PersistenceContext;
9	import jakarta.persistence.TypedQuery;
10	import java.nio.charset.StandardCharsets;
11	import java.time.Clock;
12	import java.util.ArrayList;
13	import java.util.Base64;
14	import java.util.List;
15	import java.util.Map;
16	import java.util.stream.Collectors;
17	import org.springframework.stereotype.Service;
18	import org.springframework.transaction.PlatformTransactionManager;
19	import org.springframework.transaction.support.TransactionTemplate;
20	
21	/** GET /api/orders/{id} and GET /api/orders (cursor pagination, id DESC). Lazy-expires before reading. */
22	@Service
23	public class OrderQueryService {
24	
25	    static final int DEFAULT_SIZE = 20;
26	    static final int MAX_SIZE = 100;
27	    static final int SWEEP_BATCH = 100;
28	    private static final String CURSOR_PREFIX = "o:";
29	
30	    private final PurchaseOrderRepository orderRepository;
31	    private final OrderItemRepository itemRepository;
32	    private final OrderExpiryService expiryService;
33	    private final Clock clock;
34	    private final TransactionTemplate readTx;
35	
36	    @PersistenceContext
37	    private EntityManager entityManager;
38	
39	    public OrderQueryService(PurchaseOrderRepository orderRepository, OrderItemRepository itemRepository,
40	            OrderExpiryService expiryService, Clock clock, PlatformTransactionManager transactionManager) {
41	        this.orderRepository = orderRepository;
42	        this.itemRepository = itemRepository;
43	        this.expiryService = expiryService;
44	        this.clock = clock;
45	        this.readTx = new TransactionTemplate(transactionManager);
46	        this.readTx.setReadOnly(true);
47	    }
48	
49	    public OrderResponse get(long id) {
50	        expiryService.expireIfDue(id);
51	        return readTx.execute(status -> {
52	            PurchaseOrder order = orderRepository.findById(id).orElseThrow(() -> Problems.orderNotFound(id));
53	            return OrderResponse.of(order, itemRepository.findByOrderIdOrderByIdAsc(id));
54	        });
55	    }
56	
57	    public OrderPage list(String userId, String statusParam, String sizeParam, String cursorParam) {
58	        String filterUser = parseUserId(userId);
59	        OrderStatus filterStatus = parseStatus(statusParam);
60	        int size = parseSize(sizeParam);
61	        Long cursorId = parseCursor(cursorParam);
62	
63	        expiryService.expireDueOrders(TimeSupport.now(clock), SWEEP_BATCH);
64	
65	        return readTx.execute(tx -> {
66	            StringBuilder jpql = new StringBuilder("select o from PurchaseOrder o where 1 = 1");
67	            if (filterUser != null) {
68	                jpql.append(" and o.userId = :userId");
69	            }
70	            if (filterStatus != null) {
71	                jpql.append(" and o.status = :status");
72	            }
73	            if (cursorId != null) {
74	                jpql.append(" and o.id < :cursorId");
75	            }
76	            jpql.append(" order by o.id desc");
77	            TypedQuery<PurchaseOrder> query = entityManager.createQuery(jpql.toString(), PurchaseOrder.class);
78	            if (filterUser != null) {
79	                query.setParameter("userId", filterUser);
80	            }
81	            if (filterStatus != null) {
82	                query.setParameter("status", filterStatus);
83	            }
84	            if (cursorId != null) {
85	                query.setParameter("cursorId", cursorId);
86	            }
87	            query.setMaxResults(size + 1);
88	            List<PurchaseOrder> rows = new ArrayList<>(query.getResultList());
89	            boolean hasNext = rows.size() > size;
90	            List<PurchaseOrder> page = hasNext ? rows.subList(0, size) : rows;
91	
92	            Map<Long, List<OrderItem>> itemsByOrder = page.isEmpty() ? Map.of()
93	                    : itemRepository.findByOrderIdInOrderByIdAsc(page.stream().map(PurchaseOrder::getId).toList())
94	                            .stream().collect(Collectors.groupingBy(OrderItem::getOrderId));
95	            List<OrderResponse> content = page.stream()
96	                    .map(o -> OrderResponse.of(o, itemsByOrder.getOrDefault(o.getId(), List.of()))).toList();
97	            String nextCursor = hasNext ? encodeCursor(page.get(page.size() - 1).getId()) : null;
98	            return new OrderPage(content, nextCursor);
99	        });
100	    }
101	
102	    private static String parseUserId(String userId) {
103	        if (userId == null) {
104	            return null;
105	        }
106	        if (userId.isEmpty() || userId.length() > 64) {
107	            throw Problems.invalidParameter("userId", "Parameter 'userId' must be 1-64 characters.");
108	        }
109	        return userId;
110	    }
111	
112	    private static OrderStatus parseStatus(String status) {
113	        if (status == null) {
114	            return null;
115	        }
116	        try {
117	            return OrderStatus.valueOf(status);
118	        } catch (IllegalArgumentException e) {
119	            throw Problems.invalidParameter("status", "Parameter 'status' is not a valid order status.");
120	        }
121	    }
122	
123	    private static int parseSize(String size) {
124	        if (size == null) {
125	            return DEFAULT_SIZE;
126	        }
127	        int parsed;
128	        try {
129	            parsed = Integer.parseInt(size);
130	        } catch (NumberFormatException e) {
131	            throw Problems.invalidParameter("size", "Parameter 'size' must be an integer between 1 and " + MAX_SIZE + ".");
132	        }
133	        if (parsed < 1 || parsed > MAX_SIZE) {
134	            throw Problems.invalidParameter("size", "Parameter 'size' must be an integer between 1 and " + MAX_SIZE + ".");
135	        }
136	        return parsed;
137	    }
138	
139	    static String encodeCursor(long id) {
140	        return Base64.getUrlEncoder().withoutPadding()
141	                .encodeToString((CURSOR_PREFIX + id).getBytes(StandardCharsets.UTF_8));
142	    }
143	
144	    private static Long parseCursor(String cursor) {
145	        if (cursor == null) {
146	            return null;
147	        }
148	        try {
149	            String decoded = new String(Base64.getUrlDecoder().decode(cursor), StandardCharsets.UTF_8);
150	            if (!decoded.startsWith(CURSOR_PREFIX)) {
151	                throw new IllegalArgumentException("prefix");
152	            }
153	            long id = Long.parseLong(decoded.substring(CURSOR_PREFIX.length()));
154	            if (id <= 0) {
155	                throw new IllegalArgumentException("id");
156	            }
157	            return id;
158	        } catch (IllegalArgumentException e) {
159	            throw Problems.invalidParameter("cursor", "Parameter 'cursor' is not a valid cursor.");
160	        }
161	    }
162	}
