1	package com.example.order.payment;
2	
3	import com.example.order.common.PaymentGatewayException;
4	import com.fasterxml.jackson.databind.JsonNode;
5	import com.fasterxml.jackson.databind.ObjectMapper;
6	import java.io.IOException;
7	import java.net.SocketTimeoutException;
8	import java.net.http.HttpTimeoutException;
9	import java.nio.charset.StandardCharsets;
10	import org.springframework.beans.factory.annotation.Qualifier;
11	import org.springframework.http.MediaType;
12	import org.springframework.stereotype.Component;
13	import org.springframework.web.client.ResourceAccessException;
14	import org.springframework.web.client.RestClient;
15	import org.springframework.web.client.RestClientException;
16	
17	/**
18	 * External PG calls (no automatic retry). Failure classification:
19	 * timeout -> 504; connection failure / 5xx / 4xx / malformed body -> 502 with a reason.
20	 * Never logs or stores the card token.
21	 */
22	@Component
23	public class PaymentGatewayClient {
24	
25	    public record Approval(String paymentId, boolean approved) {
26	    }
27	
28	    private record ApproveRequest(long orderId, long amount, String cardToken) {
29	        @Override
30	        public String toString() {
31	            return "ApproveRequest[orderId=" + orderId + ", amount=" + amount + ", cardToken=***]";
32	        }
33	    }
34	
35	    private record RawResponse(int status, String body) {
36	    }
37	
38	    private final RestClient restClient;
39	    private final ObjectMapper objectMapper;
40	
41	    public PaymentGatewayClient(@Qualifier("paymentGatewayRestClient") RestClient restClient,
42	            ObjectMapper objectMapper) {
43	        this.restClient = restClient;
44	        this.objectMapper = objectMapper;
45	    }
46	
47	    public Approval approve(long orderId, long amount, String cardToken, String idempotencyKey) {
48	        RawResponse raw = execute(() -> restClient.post().uri("/v1/payments")
49	                .header("Idempotency-Key", idempotencyKey)
50	                .contentType(MediaType.APPLICATION_JSON)
51	                .body(new ApproveRequest(orderId, amount, cardToken))
52	                .exchange((request, response) -> new RawResponse(response.getStatusCode().value(),
53	                        new String(response.getBody().readAllBytes(), StandardCharsets.UTF_8))));
54	        JsonNode json = parseOk(raw);
55	        String paymentId = textOf(json.get("paymentId"));
56	        String status = textOf(json.get("status"));
57	        if (paymentId == null || paymentId.isBlank() || paymentId.length() > 100) {
58	            throw PaymentGatewayException.error("BAD_RESPONSE");
59	        }
60	        if ("APPROVED".equals(status)) {
61	            return new Approval(paymentId, true);
62	        }
63	        if ("DECLINED".equals(status)) {
64	            return new Approval(paymentId, false);
65	        }
66	        throw PaymentGatewayException.error("BAD_RESPONSE");
67	    }
68	
69	    public void refund(String paymentId) {
70	        RawResponse raw = execute(() -> restClient.post().uri("/v1/payments/{paymentId}/refund", paymentId)
71	                .header("Idempotency-Key", "refund-" + paymentId)
72	                .exchange((request, response) -> new RawResponse(response.getStatusCode().value(),
73	                        new String(response.getBody().readAllBytes(), StandardCharsets.UTF_8))));
74	        JsonNode json = parseOk(raw);
75	        if (!"REFUNDED".equals(textOf(json.get("status")))) {
76	            throw PaymentGatewayException.error("BAD_RESPONSE");
77	        }
78	    }
79	
80	    private RawResponse execute(java.util.function.Supplier<RawResponse> call) {
81	        try {
82	            return call.get();
83	        } catch (RestClientException e) {
84	            throw isTimeout(e) ? PaymentGatewayException.timeout() : PaymentGatewayException.error("UNAVAILABLE");
85	        }
86	    }
87	
88	    private JsonNode parseOk(RawResponse raw) {
89	        if (raw.status() >= 500) {
90	            throw PaymentGatewayException.error("SERVER_ERROR");
91	        }
92	        if (raw.status() >= 400) {
93	            throw PaymentGatewayException.error("REJECTED");
94	        }
95	        if (raw.status() != 200) {
96	            throw PaymentGatewayException.error("BAD_RESPONSE");
97	        }
98	        try {
99	            JsonNode json = objectMapper.readTree(raw.body());
100	            if (json == null || !json.isObject()) {
101	                throw PaymentGatewayException.error("BAD_RESPONSE");
102	            }
103	            return json;
104	        } catch (IOException e) {
105	            throw PaymentGatewayException.error("BAD_RESPONSE");
106	        }
107	    }
108	
109	    private static String textOf(JsonNode node) {
110	        if (node == null || node.isNull()) {
111	            return null;
112	        }
113	        return node.isTextual() || node.isIntegralNumber() ? node.asText() : null;
114	    }
115	
116	    private static boolean isTimeout(Throwable e) {
117	        for (Throwable t = e; t != null; t = t.getCause()) {
118	            if (t instanceof HttpTimeoutException || t instanceof SocketTimeoutException) {
119	                return true;
120	            }
121	            if (t instanceof ResourceAccessException && t.getCause() == null) {
122	                return false;
123	            }
124	        }
125	        return false;
126	    }
127	}
