1	package com.example.order.order;
2	
3	import com.example.order.common.Hashing;
4	import com.example.order.common.InvalidOrderStateException;
5	import com.example.order.common.OrderExpiredException;
6	import com.example.order.common.Problems;
7	import com.example.order.common.TimeSupport;
8	import com.example.order.idempotency.IdempotencyKey;
9	import com.example.order.idempotency.IdempotencyKeyRepository;
10	import com.example.order.order.OrderDtos.OrderResponse;
11	import com.example.order.order.OrderDtos.OrderResult;
12	import com.example.order.payment.Payment;
13	import com.example.order.payment.PaymentGatewayClient;
14	import com.example.order.payment.PaymentGatewayClient.Approval;
15	import com.example.order.payment.PaymentRepository;
16	import com.example.order.payment.PaymentStatus;
17	import java.time.Clock;
18	import java.time.Instant;
19	import java.util.List;
20	import org.springframework.stereotype.Service;
21	import org.springframework.transaction.annotation.Transactional;
22	
23	/**
24	 * pay / cancel (+refund). Both run under the order row lock (FOR UPDATE) and call the PG inside the transaction
25	 * (D-09). PG failures are exceptions that are NOT in noRollbackFor, so everything (including the idempotency key)
26	 * rolls back; lazy-expiry exceptions ARE in noRollbackFor so the EXPIRED transition commits.
27	 */
28	@Service
29	public class OrderPaymentService {
30	
31	    private final PurchaseOrderRepository orderRepository;
32	    private final OrderItemRepository itemRepository;
33	    private final PaymentRepository paymentRepository;
34	    private final IdempotencyKeyRepository idempotencyRepository;
35	    private final PaymentGatewayClient gateway;
36	    private final OrderInventory inventory;
37	    private final OrderExpiryService expiryService;
38	    private final Clock clock;
39	
40	    public OrderPaymentService(PurchaseOrderRepository orderRepository, OrderItemRepository itemRepository,
41	            PaymentRepository paymentRepository, IdempotencyKeyRepository idempotencyRepository,
42	            PaymentGatewayClient gateway, OrderInventory inventory, OrderExpiryService expiryService, Clock clock) {
43	        this.orderRepository = orderRepository;
44	        this.itemRepository = itemRepository;
45	        this.paymentRepository = paymentRepository;
46	        this.idempotencyRepository = idempotencyRepository;
47	        this.gateway = gateway;
48	        this.inventory = inventory;
49	        this.expiryService = expiryService;
50	        this.clock = clock;
51	    }
52	
53	    @Transactional(noRollbackFor = { OrderExpiredException.class, InvalidOrderStateException.class })
54	    public OrderResult pay(long orderId, String idempotencyKey, String cardToken) {
55	        Instant now = TimeSupport.now(clock);
56	        PurchaseOrder order = orderRepository.findByIdForUpdate(orderId)
57	                .orElseThrow(() -> Problems.orderNotFound(orderId));
58	        String hash = Hashing.sha256Hex(orderId + "|" + cardToken);
59	
60	        // 2. replay / conflict check
61	        IdempotencyKey existing = idempotencyRepository.findByOperationAndScopeKeyAndIdemKey(IdempotencyKey.PAY,
62	                IdempotencyKey.PAY_SCOPE, idempotencyKey).orElse(null);
63	        if (existing != null) {
64	            return replayOrConflict(existing, hash, idempotencyKey, order);
65	        }
66	
67	        // 3. state check
68	        if (order.getStatus() != OrderStatus.PENDING_PAYMENT) {
69	            if (order.getStatus() == OrderStatus.EXPIRED) {
70	                throw new OrderExpiredException(orderId, order.getExpiresAt());
71	            }
72	            throw new InvalidOrderStateException(orderId, order.getStatus().name(), "pay");
73	        }
74	
75	        // 4. expiry check: commit the EXPIRED transition, then 409
76	        if (expiryService.expireLockedIfDue(order, now)) {
77	            throw new OrderExpiredException(orderId, order.getExpiresAt());
78	        }
79	
80	        // 5. claim the key (0 rows = used concurrently by another order's payment)
81	        if (idempotencyRepository.claim(IdempotencyKey.PAY, IdempotencyKey.PAY_SCOPE, idempotencyKey, hash, now) == 0) {
82	            IdempotencyKey raced = idempotencyRepository.findByOperationAndScopeKeyAndIdemKey(IdempotencyKey.PAY,
83	                    IdempotencyKey.PAY_SCOPE, idempotencyKey)
84	                    .orElseThrow(() -> new IllegalStateException("Idempotency key vanished after conflict"));
85	            return replayOrConflict(raced, hash, idempotencyKey, order);
86	        }
87	
88	        // 6. PG call; PaymentGatewayException (502/504) rolls everything back
89	        Approval approval = gateway.approve(orderId, order.getTotalPrice(), cardToken, idempotencyKey);
90	
91	        // 7. apply result
92	        List<OrderItem> items = itemRepository.findByOrderIdOrderByIdAsc(orderId);
93	        String outcome;
94	        if (approval.approved()) {
95	            order.markPaid(now);
96	            paymentRepository.save(new Payment(orderId, approval.paymentId(), PaymentStatus.APPROVED,
97	                    order.getTotalPrice(), now));
98	            inventory.confirm(order, items);
99	            outcome = "APPROVED";
100	        } else {
101	            order.transitionTo(OrderStatus.PAYMENT_FAILED, now);
102	            paymentRepository.save(new Payment(orderId, approval.paymentId(), PaymentStatus.DECLINED,
103	                    order.getTotalPrice(), now));
104	            inventory.release(order, items);
105	            outcome = "DECLINED";
106	        }
107	        idempotencyRepository.complete(IdempotencyKey.PAY, IdempotencyKey.PAY_SCOPE, idempotencyKey, orderId, outcome);
108	        return new OrderResult(OrderResponse.of(order, items), false);
109	    }
110	
111	    @Transactional(noRollbackFor = { OrderExpiredException.class, InvalidOrderStateException.class })
112	    public OrderResponse cancel(long orderId) {
113	        Instant now = TimeSupport.now(clock);
114	        PurchaseOrder order = orderRepository.findByIdForUpdate(orderId)
115	                .orElseThrow(() -> Problems.orderNotFound(orderId));
116	        expiryService.expireLockedIfDue(order, now);
117	        List<OrderItem> items = itemRepository.findByOrderIdOrderByIdAsc(orderId);
118	
119	        switch (order.getStatus()) {
120	            case PENDING_PAYMENT -> {
121	                inventory.release(order, items);
122	                order.transitionTo(OrderStatus.CANCELLED, now);
123	            }
124	            case PAID -> {
125	                Payment payment = paymentRepository.findByOrderId(orderId)
126	                        .orElseThrow(() -> new IllegalStateException("PAID order " + orderId + " has no payment"));
127	                gateway.refund(payment.getPaymentId()); // 502/504 -> rollback, order stays PAID (D-06)
128	                payment.markRefunded(now);
129	                order.transitionTo(OrderStatus.REFUNDED, now);
130	                inventory.restoreStock(order, items);
131	            }
132	            default -> throw new InvalidOrderStateException(orderId, order.getStatus().name(), "cancel");
133	        }
134	        return OrderResponse.of(order, items);
135	    }
136	
137	    private OrderResult replayOrConflict(IdempotencyKey existing, String hash, String key, PurchaseOrder lockedOrder) {
138	        if (!existing.getRequestHash().equals(hash) || existing.getOrderId() == null
139	                || !existing.getOrderId().equals(lockedOrder.getId())) {
140	            throw Problems.idempotencyKeyReused(key);
141	        }
142	        return new OrderResult(OrderResponse.of(lockedOrder,
143	                itemRepository.findByOrderIdOrderByIdAsc(lockedOrder.getId())), true);
144	    }
145	}
