28	/** POST /api/orders (01 section 2.5). One transaction; any failure rolls back reservation and idempotency key. */
29	@Service
30	public class OrderCreateService {
31	
32	    private static final String OUTCOME_CREATED = "CREATED";
33	
34	    private final ProductRepository productRepository;
35	    private final CouponRepository couponRepository;
36	    private final PurchaseOrderRepository orderRepository;
37	    private final OrderItemRepository itemRepository;
38	    private final IdempotencyKeyRepository idempotencyRepository;
39	    private final OrderProperties properties;
40	    private final Clock clock;
41	
42	    public OrderCreateService(ProductRepository productRepository, CouponRepository couponRepository,
43	            PurchaseOrderRepository orderRepository, OrderItemRepository itemRepository,
44	            IdempotencyKeyRepository idempotencyRepository, OrderProperties properties, Clock clock) {
45	        this.productRepository = productRepository;
46	        this.couponRepository = couponRepository;
47	        this.orderRepository = orderRepository;
48	        this.itemRepository = itemRepository;
49	        this.idempotencyRepository = idempotencyRepository;
50	        this.properties = properties;
51	        this.clock = clock;
52	    }
53	
54	    @Transactional
55	    public OrderResult create(String userId, String idempotencyKey, CreateOrderRequest request) {
56	        Instant now = TimeSupport.now(clock);
57	        String hash = Hashing.sha256Hex(canonical(request));
58	
59	        // 3. claim the key (waits for a concurrent in-flight claim of the same key)
60	        if (idempotencyRepository.claim(IdempotencyKey.CREATE_ORDER, userId, idempotencyKey, hash, now) == 0) {
61	            return replay(userId, idempotencyKey, hash);
62	        }
63	
64	        // 4. products (ascending id); nothing has been changed yet
65	        List<ItemRequest> sortedItems = request.items().stream()
66	                .sorted(Comparator.comparing(ItemRequest::productId)).toList();
67	        Map<Long, Product> products = productRepository
68	                .findAllById(sortedItems.stream().map(ItemRequest::productId).toList()).stream()
69	                .collect(Collectors.toMap(Product::getId, Function.identity()));
70	        for (ItemRequest item : sortedItems) {
71	            if (!products.containsKey(item.productId())) {
72	                throw Problems.productNotFound(item.productId());
73	            }
74	        }
75	
76	        // snapshot items in request order, compute subtotal
77	        List<OrderItem> orderItems = new ArrayList<>();
78	        long subtotal = 0;
79	        for (ItemRequest item : request.items()) {
80	            long unitPrice = products.get(item.productId()).getPrice();
81	            int quantity = item.quantity().intValue();
82	            subtotal = Math.addExact(subtotal, Math.multiplyExact(unitPrice, (long) quantity));
83	            orderItems.add(new OrderItem(null, item.productId(), quantity, unitPrice));
84	        }
85	
86	        // 5. coupon pre-check
87	        String couponCode = request.couponCode();
88	        Coupon coupon = null;
89	        if (couponCode != null) {
90	            coupon = couponRepository.findByCode(couponCode).orElseThrow(() -> Problems.couponNotFound(couponCode));
91	            checkApplicable(coupon, subtotal, now);
92	        }
93	
94	        // 6. reserve stock (ascending product id)
95	        for (ItemRequest item : sortedItems) {
96	            int quantity = item.quantity().intValue();
97	            if (productRepository.reserve(item.productId(), quantity) != 1) {
98	                Integer available = productRepository.findAvailable(item.productId());
99	                throw Problems.insufficientStock(item.productId(), quantity, available == null ? 0 : available);
100	            }
101	        }
102	
103	        // 7. use coupon (after products)
104	        long discount = 0;
105	        if (coupon != null) {
106	            if (couponRepository.use(couponCode, now) != 1) {
107	                throw Problems.couponNotApplicable(couponCode, "EXHAUSTED");
108	            }
109	            discount = coupon.discountFor(subtotal);
110	        }
111	
112	        // 8. persist order + items, finish the idempotency record
113	        PurchaseOrder order = orderRepository.save(new PurchaseOrder(userId, couponCode, subtotal, discount, now,
114	                now.plus(properties.paymentTtl())));
115	        List<OrderItem> savedItems = itemRepository.saveAll(orderItems.stream()
116	                .map(i -> new OrderItem(order.getId(), i.getProductId(), i.getQuantity(), i.getUnitPrice()))
117	                .toList());
118	        idempotencyRepository.complete(IdempotencyKey.CREATE_ORDER, userId, idempotencyKey, order.getId(),
119	                OUTCOME_CREATED);
120	        return new OrderResult(OrderResponse.of(order, savedItems), false);
121	    }
122	
123	    private OrderResult replay(String userId, String idempotencyKey, String hash) {
124	        IdempotencyKey existing = idempotencyRepository
125	                .findByOperationAndScopeKeyAndIdemKey(IdempotencyKey.CREATE_ORDER, userId, idempotencyKey)
126	                .orElseThrow(() -> new IllegalStateException("Idempotency key vanished after conflict"));
127	        if (!existing.getRequestHash().equals(hash)) {
128	            throw Problems.idempotencyKeyReused(idempotencyKey);
129	        }
130	        if (existing.getOrderId() == null) {
131	            throw new IllegalStateException("Idempotency key has no order");
132	        }
133	        PurchaseOrder order = orderRepository.findById(existing.getOrderId())
134	                .orElseThrow(() -> new IllegalStateException("Order of idempotency key missing"));
135	        return new OrderResult(OrderResponse.of(order, itemRepository.findByOrderIdOrderByIdAsc(order.getId())), true);
136	    }
137	
138	    private static void checkApplicable(Coupon coupon, long subtotal, Instant now) {
139	        String code = coupon.getCode();
140	        if (now.isBefore(coupon.getValidFrom())) {
141	            throw Problems.couponNotApplicable(code, "NOT_YET_VALID");
142	        }
143	        if (!now.isBefore(coupon.getValidUntil())) {
144	            throw Problems.couponNotApplicable(code, "EXPIRED");
145	        }
146	        if (subtotal < coupon.getMinOrderAmount()) {
147	            throw Problems.couponNotApplicable(code, "BELOW_MIN_ORDER_AMOUNT");
148	        }
149	        if (coupon.getUsedCount() >= coupon.getTotalQuantity()) {
150	            throw Problems.couponNotApplicable(code, "EXHAUSTED");
151	        }
152	    }
153	
154	    /** items sorted by productId as "productId:quantity", then "|" and the coupon code (or empty). */
155	    static String canonical(CreateOrderRequest request) {
156	        String items = request.items().stream()
157	                .sorted(Comparator.comparing(ItemRequest::productId))
158	                .map(i -> i.productId() + ":" + i.quantity())
159	                .collect(Collectors.joining(","));
160	        return items + "|" + (request.couponCode() == null ? "" : request.couponCode());
161	    }
162	}
