4	import com.example.order.common.Problems;
5	import com.example.order.common.TimeSupport;
6	import com.example.order.order.OrderDtos.OrderResponse;
7	import java.time.Clock;
8	import java.time.Instant;
9	import org.springframework.stereotype.Service;
10	import org.springframework.transaction.annotation.Transactional;
11	
12	/** ship (PAID -> SHIPPED) and deliver (SHIPPED -> DELIVERED). */
13	@Service
14	public class OrderFulfillmentService {
15	
16	    private final PurchaseOrderRepository orderRepository;
17	    private final OrderItemRepository itemRepository;
18	    private final OrderExpiryService expiryService;
19	    private final Clock clock;
20	
21	    public OrderFulfillmentService(PurchaseOrderRepository orderRepository, OrderItemRepository itemRepository,
22	            OrderExpiryService expiryService, Clock clock) {
23	        this.orderRepository = orderRepository;
24	        this.itemRepository = itemRepository;
25	        this.expiryService = expiryService;
26	        this.clock = clock;
27	    }
28	
29	    @Transactional(noRollbackFor = InvalidOrderStateException.class)
30	    public OrderResponse ship(long orderId) {
31	        return transition(orderId, OrderStatus.PAID, OrderStatus.SHIPPED, "ship");
32	    }
33	
34	    @Transactional(noRollbackFor = InvalidOrderStateException.class)
35	    public OrderResponse deliver(long orderId) {
36	        return transition(orderId, OrderStatus.SHIPPED, OrderStatus.DELIVERED, "deliver");
37	    }
38	
39	    private OrderResponse transition(long orderId, OrderStatus from, OrderStatus to, String action) {
40	        Instant now = TimeSupport.now(clock);
41	        PurchaseOrder order = orderRepository.findByIdForUpdate(orderId)
42	                .orElseThrow(() -> Problems.orderNotFound(orderId));
43	        expiryService.expireLockedIfDue(order, now);
44	        if (order.getStatus() != from) {
45	            throw new InvalidOrderStateException(orderId, order.getStatus().name(), action);
46	        }
47	        order.transitionTo(to, now);
48	        return OrderResponse.of(order, itemRepository.findByOrderIdOrderByIdAsc(orderId));
49	    }
50	}
