1	package com.example.order.order;
2	
3	import com.example.order.common.TimeSupport;
4	import java.time.Clock;
5	import java.time.Instant;
6	import java.util.List;
7	import org.slf4j.Logger;
8	import org.slf4j.LoggerFactory;
9	import org.springframework.data.domain.PageRequest;
10	import org.springframework.stereotype.Service;
11	import org.springframework.transaction.PlatformTransactionManager;
12	import org.springframework.transaction.support.TransactionTemplate;
13	
14	/**
15	 * Order expiry (D-08): scheduler sweep + lazy expiry. Each order is processed in its own transaction using
16	 * FOR UPDATE SKIP LOCKED so an in-flight payment is never touched.
17	 */
18	@Service
19	public class OrderExpiryService {
20	
21	    private static final Logger log = LoggerFactory.getLogger(OrderExpiryService.class);
22	
23	    private final PurchaseOrderRepository orderRepository;
24	    private final OrderItemRepository itemRepository;
25	    private final OrderInventory inventory;
26	    private final Clock clock;
27	    private final TransactionTemplate tx;
28	
29	    public OrderExpiryService(PurchaseOrderRepository orderRepository, OrderItemRepository itemRepository,
30	            OrderInventory inventory, Clock clock, PlatformTransactionManager transactionManager) {
31	        this.orderRepository = orderRepository;
32	        this.itemRepository = itemRepository;
33	        this.inventory = inventory;
34	        this.clock = clock;
35	        this.tx = new TransactionTemplate(transactionManager);
36	    }
37	
38	    /** Expires up to {@code batch} due orders; returns how many were actually transitioned. */
39	    public int expireDueOrders(Instant now, int batch) {
40	        List<Long> ids = orderRepository.findDueIds(OrderStatus.PENDING_PAYMENT, now, PageRequest.of(0, batch));
41	        int expired = 0;
42	        for (Long id : ids) {
43	            try {
44	                if (expireOne(id, now)) {
45	                    expired++;
46	                }
47	            } catch (RuntimeException e) {
48	                log.error("Failed to expire order {}", id, e);
49	            }
50	        }
51	        return expired;
52	    }
53	
54	    /** Lazy expiry for one order in its own transaction; skipped if the row is locked or not due. */
55	    public boolean expireIfDue(long orderId) {
56	        return expireOne(orderId, TimeSupport.now(clock));
57	    }
58	
59	    private boolean expireOne(long orderId, Instant now) {
60	        return Boolean.TRUE.equals(tx.execute(status ->
61	                orderRepository.lockDueSkipLocked(orderId, now).map(order -> expireLocked(order, now)).orElse(false)));
62	    }
63	
64	    /**
65	     * Expires an order the caller already holds a FOR UPDATE lock on, inside the caller's transaction.
66	     * Re-checks status and expiry under the lock. Returns true if the transition happened.
67	     */
68	    public boolean expireLockedIfDue(PurchaseOrder order, Instant now) {
69	        return order.isDue(now) && expireLocked(order, now);
70	    }
71	
72	    private boolean expireLocked(PurchaseOrder order, Instant now) {
73	        if (!order.isDue(now)) {
74	            return false;
75	        }
76	        inventory.release(order, itemRepository.findByOrderIdOrderByIdAsc(order.getId()));
77	        order.transitionTo(OrderStatus.EXPIRED, now);
78	        return true;
79	    }
80	}
