1	package com.example.order.order;
2	
3	import com.example.order.coupon.CouponRepository;
4	import com.example.order.product.ProductRepository;
5	import java.util.Comparator;
6	import java.util.List;
7	import org.springframework.stereotype.Component;
8	
9	/**
10	 * Stock/coupon side effects of order state transitions (01 section 8). Must run inside the transition's
11	 * transaction, products in ascending id order first, then the coupon (lock order, 02 section 3.4).
12	 */
13	@Component
14	public class OrderInventory {
15	
16	    private final ProductRepository productRepository;
17	    private final CouponRepository couponRepository;
18	
19	    public OrderInventory(ProductRepository productRepository, CouponRepository couponRepository) {
20	        this.productRepository = productRepository;
21	        this.couponRepository = couponRepository;
22	    }
23	
24	    /** CANCELLED / EXPIRED / PAYMENT_FAILED from PENDING_PAYMENT: reserved -= q, coupon used_count -= 1. */
25	    public void release(PurchaseOrder order, List<OrderItem> items) {
26	        for (OrderItem item : sorted(items)) {
27	            if (productRepository.release(item.getProductId(), item.getQuantity()) != 1) {
28	                throw new IllegalStateException("Reservation invariant violated for product " + item.getProductId()
29	                        + " (order " + order.getId() + ")");
30	            }
31	        }
32	        if (order.getCouponCode() != null && couponRepository.restore(order.getCouponCode()) != 1) {
33	            throw new IllegalStateException("Coupon usage invariant violated for order " + order.getId());
34	        }
35	    }
36	
37	    /** PAID: stock -= q, reserved -= q. Coupon stays consumed. */
38	    public void confirm(PurchaseOrder order, List<OrderItem> items) {
39	        for (OrderItem item : sorted(items)) {
40	            if (productRepository.confirm(item.getProductId(), item.getQuantity()) != 1) {
41	                throw new IllegalStateException("Stock confirm invariant violated for product " + item.getProductId()
42	                        + " (order " + order.getId() + ")");
43	            }
44	        }
45	    }
46	
47	    /** REFUNDED: stock += q. Coupon is NOT restored (D-02). */
48	    public void restoreStock(PurchaseOrder order, List<OrderItem> items) {
49	        for (OrderItem item : sorted(items)) {
50	            if (productRepository.restoreStock(item.getProductId(), item.getQuantity()) != 1) {
51	                throw new IllegalStateException("Stock restore failed for product " + item.getProductId()
52	                        + " (order " + order.getId() + ")");
53	            }
54	        }
55	    }
56	
57	    private static List<OrderItem> sorted(List<OrderItem> items) {
58	        return items.stream().sorted(Comparator.comparing(OrderItem::getProductId)).toList();
59	    }
60	}
