        }

        @Test
        @DisplayName("REQ-10 이미 PAID 인 주문에 새 키로 결제 -> 409 invalid-order-state, PG 재호출 없음, 재고 이중 차감 없음")
        void payingPaidOrderAgainIsInvalidState() {
            long p = api.newProduct(1000, 10);
            long orderId = api.orderOk(p, 2).get("id").asLong();
            api.payOk(orderId);
